    "notes": "第一张个人专辑。2004年10月-12月录于南京（华博广告公司、新力广告公司录音室），制作人/编曲李志、刘威，录音混音刘威。发行时未署名李志而署网名B&B。《红色气球》为其第一首创作并录制成型的歌。百度百科原版曲目含《青春》并注明口袋唱片版未收录；粉丝档案站所载口袋版为8曲无《青春》。豆瓣条目记发行时间2004-12。",
