 "quotes": [
  {
   "text": "我的音乐很一般，我是个天赋平平的人。",
   "source": "澎湃新闻专访《李志：我绝对是这个圈子里最不装×的前三名》，2015年"
  },
  {
   "text": "写了这么多歌，我没有特别喜欢的，只有非常讨厌的。",
   "source": "网易音乐人专题《一个音乐个体户的跨年之路》访谈，2014年"
  },
  {
   "text": "如果批评是不厚道，我一直在不厚道，还会继续不厚道。",
   "source": "澎湃新闻专访（谈点评同行），2015年"
  },
  {
   "text": "所谓今天的不要脸，是为了明天大踏步的要脸。",
   "source": "澎湃新闻专访（谈打破不接受采访的原则），2015年"
  },
  {
   "text": "如果我发现有一件我更喜欢的事情，我会毫不犹豫去做。",
   "source": "《南方人物周刊》《李志：黑夜里寻找一点点欢愉》，2018年1月"
  }
 ],
